<section class="panel agent-panel" id="agent-performance"><div class="panel-heading"><div><h2 id="agent-performance-heading">Agent performance</h2><p>Sorted by response volume · <?= number_format($agentCount) ?> agent/team combinations<?= !$personal ? ' · Select a name for details' : '' ?></p></div><a class="text-link" href="#dashboard-filters">Edit filters ↑</a></div><div class="table-scroll report-detail-scroll" role="region" aria-labelledby="agent-performance-heading" tabindex="0"><table><thead><tr><th scope="col">Agent</th><th scope="col">Team</th><th scope="col" class="number">Responses</th><th scope="col" class="number">Good</th><th scope="col" class="number">Bad</th><th scope="col" class="number">CSAT</th></tr></thead><tbody><?php foreach ($agents as $agent): ?><tr><td class="agent-name"><?php if (!$personal): ?><a class="text-link" href="<?= esc(\App\Libraries\Modules::url('admin/agents/' . $agent['response_id']) . '?' . http_build_query($filters)) ?>"><?= esc($agent['agent_name']) ?></a><?php else: ?><?= esc($agent['agent_name']) ?><?php endif ?></td><td><span class="tag"><?= esc($agent['team']) ?></span></td><td class="number"><?= number_format($agent['total']) ?></td><td class="number"><?= number_format($agent['good']) ?></td><td class="number"><?= number_format($agent['bad']) ?></td><td class="number score"><?= $agent['score'] !== null ? number_format($agent['score'], 2) . '%' : '—' ?></td></tr><?php endforeach ?></tbody></table></div><nav class="pagination" aria-label="Agent performance pages"><span><?= number_format(($page - 1) * 25 + 1) ?>–<?= number_format(min($page * 25, $agentCount)) ?> of <?= number_format($agentCount) ?> <span class="pagination-page">· Page <?= $page ?> of <?= $pages ?></span></span><div><?php if ($page > 1): ?><a class="button secondary small-button" rel="prev" href="<?= esc(\App\Libraries\Modules::url('dashboard') . '?' . http_build_query(array_merge($filters, ['import' => $import['id'], 'page' => $page - 1]))) ?>#agent-performance">← Previous</a><?php endif ?><?php if ($page < $pages): ?><a class="button secondary small-button" rel="next" href="<?= esc(\App\Libraries\Modules::url('dashboard') . '?' . http_build_query(array_merge($filters, ['import' => $import['id'], 'page' => $page + 1]))) ?>#agent-performance">Next →</a><?php endif ?></div></nav></section>
